def transform(grid):
    g=[row[:] for row in grid]
    H=len(g); W=len(g[0])
    threes=[(r,c) for r in range(H) for c in range(W) if g[r][c]==3]
    fours=[(r,c) for r in range(H) for c in range(W) if g[r][c]==4]
    if not threes: return g
    rs=[r for r,c in threes]; cs=[c for r,c in threes]
    rmin,rmax=min(rs),max(rs); cmin,cmax=min(cs),max(cs)
    for (r,c) in fours:
        cands=[]
        if c>cmax: cands.append((c-cmax,(0,-1)))
        if c<cmin: cands.append((cmin-c,(0,1)))
        if r>rmax: cands.append((r-rmax,(-1,0)))
        if r<rmin: cands.append((rmin-r,(1,0)))
        if not cands: continue
        cands.sort()
        dr,dc=cands[0][1]
        nr,nc=r+dr,c+dc
        while 0<=nr<H and 0<=nc<W and g[nr][nc]!=3:
            g[nr][nc]=4
            nr+=dr; nc+=dc
    return g
